const body = $json.body || $json;

if (!body.document_field_extraction_id) {
  throw new Error('document_field_extraction_id is required');
}
if (!body.reviewed_fields || typeof body.reviewed_fields !== 'object') {
  throw new Error('reviewed_fields (object) is required');
}

return [
  {
    json: {
      document_field_extraction_id: body.document_field_extraction_id,
      reviewed_fields: JSON.stringify(body.reviewed_fields)
    }
  }
];

const row = $input.first().json;
const reviewed = row.reviewed_fields || {};

const pumpEquipmentNumber = reviewed.pump_equipment_number?.value || null;
const sealType = reviewed.seal_type?.value || null;

return [{ json: { ...row, pump_candidate: pumpEquipmentNumber, seal_candidate: sealType } }];

const context = $('Build Identity Candidates').first().json;
const knownPumps = $('Query Candidate Pumps').all().map(item => item.json);
const knownSeals = $('Query Candidate Seals').all().map(item => item.json);

const escapeForShell = (s) => "'" + s.replace(/'/g, "'\\''") + "'";

const pumpPayload = JSON.stringify({
  candidate_key: { tag_number: context.pump_candidate },
  known: knownPumps
});
const sealPayload = JSON.stringify({
  candidate_key: { seal_code: context.seal_candidate },
  known: knownSeals
});

return [{
  json: {
    document_field_extraction_id: context.document_field_extraction_id,
    pump_resolve_command: `echo ${escapeForShell(pumpPayload)} | python "PRODUCTS/LTSA-BRAIN/AI-EXTRACTION/resolve_identity_cli.py" --object-type PUMP`,
    seal_resolve_command: `echo ${escapeForShell(sealPayload)} | python "PRODUCTS/LTSA-BRAIN/AI-EXTRACTION/resolve_identity_cli.py" --object-type SEAL`
  }
}];

const pumpResult = JSON.parse(($('Run Pump Identity Resolution').first().json.stdout || '{}'));
const sealResult = JSON.parse(($('Run Seal Identity Resolution').first().json.stdout || '{}'));
const context = $('Build Resolve Commands').first().json;

return [{
  json: {
    document_field_extraction_id: context.document_field_extraction_id,
    pump_tag_number: pumpResult.matched ? $('Build Identity Candidates').first().json.pump_candidate : null,
    seal_code: sealResult.matched ? sealResult.canonical_id : null
  }
}];
